'use strict';
const R=window.Reunion,KEY='okazaki-kita-1987-public-demo-v1',main=document.querySelector('#main');
let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(KEY)||'null');if(!state||state.schema!==1)state=R.seed();}catch{state=R.seed();storageOK=false;}
let actor='幹事A（サンプル）',draft=null,selectedPerson=Number(sessionStorage.getItem('kita-demo-person')||1),editId=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yen=v=>Number(v).toLocaleString('ja-JP')+'円';
const date=v=>v?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';
const label={active:'参加予定',attended:'当日参加確認済',cancel_requested:'欠席変更申請中',cancelled:'欠席・取消済',pending:'確認待ち',confirmed:'確認済',excluded:'除外済'};
const pill=(s,warn=false)=>'<span class="status '+(warn?'status-warn':'')+'">'+esc(label[s]||s)+'</span>';
function toast(t){const x=document.querySelector('#toast');x.textContent=t;x.classList.add('visible');setTimeout(()=>x.classList.remove('visible'),3500);}
function change(fn){const next=R.clone(state);let result;try{result=fn(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;return result;}catch(err){if(err.name==='QuotaExceededError')throw new Error('この端末の保存容量がいっぱいです。追加した画像を非表示にするか、デモを初期化してください。');throw err;}}
function failed(action,entity,error){try{change(s=>R.audit(s,actor,action,entity,null,null,error.message,'失敗・未確定'));}catch{}toast(error.message);}
function download(name,data,type='text/csv;charset=utf-8'){const b=new Blob([data],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function field(name,title,value='',type='text',required=true,help=''){return '<label class="field">'+esc(title)+(required?'<span class="required">必須</span>':'')+(help?' <small>'+esc(help)+'</small>':'')+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(required?'required':'')+' maxlength="'+(type==='date'?'10':'200')+'"></label>';}
function select(name,title,items,value){return '<label class="field">'+esc(title)+'<select name="'+name+'">'+items.map(([v,t])=>'<option value="'+esc(v)+'" '+(String(v)===String(value)?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label>';}
function title(k,t,p=''){return '<div class="page-title"><div class="eyebrow">'+k+'</div><h1>'+t+'</h1>'+(p?'<p>'+p+'</p>':'')+'</div>';}
const notice='<div class="notice">操作確認専用です。実際の個人情報・銀行明細・写真は入力しないでください。保存先はこのブラウザーだけで、ほかの閲覧者とは共有されません。</div>';
function frame(body,cls=''){return '<div class="container '+cls+'">'+body+'</div>';}
function classCards(){const c=R.counts(state);return '<div class="classes-grid">'+c.classes.map((n,i)=>'<a class="class-card" href="#/classes/'+(i+1)+'"><span class="label">3年'+(i+1)+'組</span><span class="arrow">↗</span><strong>'+n+'<small>人</small></strong><div class="bar"><span style="width:'+Math.min(100,Math.round(n*100/Number(state.settings.classSize||47)))+'%"></span></div></a>').join('')+'</div>';}
function homeDate(date){const m=String(date).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[1]+'年'+Number(m[2])+'月'+Number(m[3])+'日':String(date);}
function eventOverview(s){return `<section class="event-overview" aria-label="開催概要・受付案内"><p class="overview-note">開催日・会費・受付日程は、表示確認用の仮設定です。正式なご案内まで実際の受付・お振込はできません。</p><div class="overview-row"><div class="overview-label">WHEN<span>開催日（仮）</span></div><div class="overview-content"><strong>${esc(s.dateLabel)}</strong><p>開催時刻は決まり次第ご案内します。</p></div></div><div class="overview-row"><div class="overview-label">WHERE<span>会場</span></div><div class="overview-content"><strong>${esc(s.venue)}</strong><p>懐かしい岡崎で、再会のひとときを。</p></div></div><div class="overview-row"><div class="overview-label">PARTICIPATION<span>会費・お申し込み（仮）</span></div><div class="overview-content"><p class="registration-label">申込受付期間</p><div class="registration-period"><span>${esc(homeDate(s.open))}</span><span>〜 ${esc(homeDate(s.registration))}</span></div><p class="participation-fee">会費 <strong>${yen(s.fee)}</strong><small>（仮）</small></p></div></div></section>`;}
function applicationSchedule(s){return '<section class="application-schedule"><div class="eyebrow">APPLICATION GUIDE</div><h2>会費・お申し込みの期限</h2><p>以下は表示確認用の仮設定です。</p><dl class="overview-dates"><div><dt>会費（仮）</dt><dd>'+yen(s.fee)+'</dd></div>'+[['registration','申込期限'],['payment','入金期限'],['change','内容変更期限'],['cancel','キャンセル期限']].map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+esc(homeDate(s[key]))+'</dd></div>').join('')+'</dl><p class="mini-note">内容変更・欠席の申請はログイン後の「申込確認」から行えます。各期限は幹事の設定により変更される場合があります。</p></section>';}
function home(){const c=R.counts(state);return frame(`<section class="hero"><div><div class="eyebrow">OKAZAKI KITA HIGH SCHOOL · REUNION</div><h1>あの頃の続き、<br><em>ここで。</em></h1><p class="lead reunion-title"><span>岡崎北高等学校</span><span>1987年卒同窓会</span></p><p class="hero-sub">チャイムの音も、放課後の寄り道も。<br>思い出は違っても、話し始めればきっと、あの頃へ。<br>2028年、懐かしい顔に会いに来ませんか。</p><div class="actions"><a class="btn" href="#/register">参加申込を試してみる <span>↗</span></a><a class="btn btn-outline" href="#/classes">誰が来るかな？ <span>→</span></a></div><p class="hero-fine">ただいま幹事・同窓生向けのサンプルを公開中。本番受付は準備中です。</p></div><div class="hero-art"><span class="hero-year" aria-hidden="true">1987</span><div class="photo-card"><img class="school-photo" src="assets/okazaki-kita-school.jpg" alt="岡崎北高等学校の校舎" width="960" height="720"><p class="handwriting">Good to see you again.</p></div><div class="year-tag" aria-label="1987年から2028年へ、また会おう"><span class="badge-years"><span>1987</span><span class="badge-arrow" aria-hidden="true">↓</span><span>2028</span></span><small>MEET AGAIN</small></div><span class="art-note">岡崎北高等学校の校舎</span></div></section>${eventOverview(state.settings)}<section class="section"><div class="section-head"><div><div class="eyebrow">FIND YOUR CLASSMATES</div><h2>みんな、集まってきています。</h2><p>あなたのクラスは何人？懐かしい名前を探してみてください。</p></div><div class="total-badge">全体の参加予定 <b>${c.total}</b>人<span>（架空サンプル）</span></div></div>${classCards()}<p class="section-note">※ 人物・人数はすべて架空です。人数には名前を掲載しない設定の方も含みます。</p></section>`)+`<section class="message-section"><div class="container message-grid"><div class="message-title">Long time,<br>no see.<span>また会える、その日まで。</span></div><div class="message-copy"><div class="eyebrow">A NOTE FOR OUR CLASSMATES</div><h2>「久しぶり！」から、はじめよう。</h2><p>あの教室を出てから、それぞれの道を歩いてきた私たち。<br>大人になった今だからこそ、話せることも、笑えることも。<br>肩書きも近況も、ひとまず置いて。<br>懐かしい友人と、気軽に集まれる時間をつくっていきます。</p><p class="message-sign">1987年卒同窓会 幹事会より <small>（案内文サンプル）</small></p></div></div></section>`+frame(`<section class="section"><div class="section-head"><div><div class="eyebrow">OUR PHOTO ALBUM</div><h2>思い出は、これからも増えていく。</h2><p>当日の写真を、みんなで楽しむアルバムに。</p></div><a href="#/gallery" class="text-link">アルバムをのぞく ↗</a></div><div class="gallery-grid">${albumCards(state.photos.filter(p=>p.published).slice(0,3))}</div><p class="section-note">※ 現在はイラストの見本です。本番の写真は参加者限定で公開する予定です。</p></section><section class="cta-section"><div><div class="eyebrow" style="color:#dfdfb2">SEE YOU IN OKAZAKI</div><h2>会いたい顔が、きっといる。</h2><p>まずは申込の流れを、サンプルで体験してみませんか。</p></div><a href="#/register" class="btn btn-light">参加申込を試す ↗</a></section><section class="section"><div class="section-head"><div><div class="eyebrow">QUESTIONS & ANSWERS</div><h2>気になること、いくつか。</h2></div></div><div class="faq-list"><details><summary>このページで、本当に参加申込できますか？</summary><p>今はデザインと操作を確認するためのサンプルです。実際の申込・メール送信・振込は行いません。架空の内容でお試しください。</p></details><details><summary>名前や住所は、みんなに見えますか？</summary><p>名簿には掲載を選んだ表示名だけを出す構成です。本番では住所・電話・メール・入金情報は幹事だけが確認します。今はすべて架空のデータで、幹事画面も自由に体験できます。</p></details><details><summary>申込後に変更や欠席の連絡はできますか？</summary><p>内容修正とキャンセルの期限をそれぞれ設定します。期限内なら申込確認ページから変更・欠席申請できます。幹事画面で設定と操作を試せます。</p></details><details><summary>スマートフォンやLINEから見られますか？</summary><p>はい。URLを開くだけで見られるサンプルです。操作内容は端末・ブラウザーごとに保存されます。LINE内ブラウザーとSafariなどを切り替えると、データは別になります。</p></details></div></section>`);}
function albumCards(photos){return photos.map(p=>`<a class="album-card" href="#/photo/${p.id}"><img src="${esc(p.src)}" alt="${esc(p.title)}"><div class="album-title"><span>${esc(p.title)}</span><span>↗</span></div><small>${esc(p.album)} · ${p.sample?'イラスト見本':'この端末だけの追加画像'}</small></a>`).join('');}
function classes(cl){cl=Number(cl)||0;const c=R.counts(state);let ps=state.people.filter(p=>R.active(p)&&p.public&&(!cl||p.class===cl));ps.sort((a,b)=>a.class-b.class||a.kana.localeCompare(b.kana,'ja'));return frame(title('CLASSMATES',cl?'3年'+cl+'組の、懐かしい顔ぶれ。':'みんなの参加予定','名前は架空のサンプルです。住所・電話・メール・入金状況はこの名簿には表示しません。')+`<div class="panel"><div class="section-head"><div><h2>${cl?'3年'+cl+'組':'全クラス'}の参加予定 <span class="amount">${cl?c.classes[cl-1]:c.total}</span> 人</h2><p>全体の参加予定：${c.total}人（架空）</p></div><a href="#/register" class="btn btn-small">自分も参加申込を試す ↗</a></div><div class="class-tabs"><a href="#/classes" class="${!cl?'active':''}">全クラス</a>${c.classes.map((n,i)=>`<a href="#/classes/${i+1}" class="${cl===i+1?'active':''}">3年${i+1}組 <small>${n}人</small></a>`).join('')}</div><div class="roster">${ps.map(p=>'<div class="name-card"><small>3年'+p.class+'組</small><strong>'+esc(p.display)+'</strong><small>架空の同窓生</small></div>').join('')||'<p class="empty">掲載中の参加予定者はいません。</p>'}</div><p class="section-note">人数には名前を掲載していない方も含みます。欠席変更申請中・取消済みの方は参加予定人数から除外しています。</p></div>`);}
function personForm(p={}){return `<div class="grid-2">${select('class','卒業時のクラス',Array.from({length:10},(_,i)=>[i+1,'3年'+(i+1)+'組']),p.class||1)}${field('name','氏名',p.name||'')}${field('kana','ふりがな',p.kana||'')}${field('oldname','卒業時の姓・旧姓',p.oldname||'','text',false)}${field('email','メールアドレス',p.email||'','email',true,'@example.test の架空アドレスをご利用ください')}${field('emailConfirm','メールアドレス（確認）',p.email||'','email')}${field('postal','郵便番号',p.postal||'000-0000')}${field('address','住所',p.address||'')}${field('phone','電話番号',p.phone||'')}${field('payer','振込名義（カタカナ）',p.payer||'','text',true,'例：ヤマダ タロウ。ひらがな・半角カナはカタカナに自動変換します。漢字の場合は読みを入力してください。')}${field('display','名簿に表示する名前',p.display||p.name||'','text',false)}</div><label class="field">名前の掲載<select name="public" required><option value="">掲載の選択をしてください</option><option value="yes" ${p.public===true?'selected':''}>名前を名簿に掲載する</option><option value="no" ${p.public===false?'selected':''}>名前を掲載しない（人数には含む）</option></select></label><label class="field">幹事へのメモ <small>任意・一般名簿には表示しません</small><textarea name="note" maxlength="1000">${esc(p.note||'')}</textarea></label><label class="field"><input type="checkbox" name="sampleOnly" required>架空の情報で操作するサンプルであることを確認しました。</label>`;}
function registerPage(){let p=draft||{};if(editId)p=state.people.find(p=>p.id===editId)||p;return frame(title('REGISTRATION',editId?'参加申込の内容を変更する。':'また会う約束を、ここから。','個人で1名ずつ申し込む流れをお試しいただけます。')+notice+`<div class="panel"><div class="stepper"><span class="current">01 入力</span><span>02 確認</span><span>03 完了</span></div><div class="notice notice-green">仮会費 ${yen(state.settings.fee)} ／ 申込期限 ${esc(state.settings.registration)} ／ 内容修正期限 ${esc(state.settings.change)}<br>これらは操作確認用の仮設定です。会費・日程の正式発表ではありません。</div><button class="btn btn-outline btn-small" id="fillDemo" type="button">架空のサンプル情報を自動入力</button><form id="registrationForm">${personForm(p)}<p id="formError" class="error-text" role="alert"></p><button class="btn" type="submit">入力内容を確認する →</button></form></div>`,'narrow');}
function draftFrom(f){const d=Object.fromEntries(new FormData(f));if(d.email!==d.emailConfirm)throw new Error('メールアドレスが一致していません。');if(!['yes','no'].includes(d.public))throw new Error('名簿掲載の可否を選択してください。');return {class:Number(d.class),name:d.name.trim(),kana:d.kana.trim(),oldname:d.oldname.trim(),email:d.email.trim(),postal:d.postal.trim(),address:d.address.trim(),phone:d.phone.trim(),payer:R.normalizePayer(d.payer),display:d.display.trim()||d.name.trim(),public:d.public==='yes',note:d.note};}
function confirmPage(){if(!draft)return frame(title('REGISTRATION','入力内容がありません。')+'<a class="btn" href="#/register">入力へ戻る</a>','narrow');const d=draft;return frame(title('CONFIRM','この内容で、よろしいですか。')+notice+`<div class="panel"><div class="stepper"><span>01 入力</span><span class="current">02 確認</span><span>03 完了</span></div>${details([['クラス','3年'+d.class+'組'],['氏名',d.name],['ふりがな',d.kana],['メール',d.email],['住所',d.postal+' '+d.address],['電話番号',d.phone],['申告名義',d.payer],['名前の掲載',d.public?d.display+'（この名前だけを名簿へ）':'掲載しない・人数にのみ含める'],['仮会費',yen(editId?state.people.find(p=>p.id===editId).amount:state.settings.fee)]])}<div class="button-row"><button id="confirmRegistration" class="btn">${editId?'変更を保存する':'サンプル申込を確定する'} →</button><a class="btn btn-outline" href="#/register${editId?'/'+editId:''}">入力に戻る</a></div></div>`,'narrow');}
function details(rows){return '<dl class="details-grid">'+rows.map(([a,b])=>'<dt>'+esc(a)+'</dt><dd>'+esc(b)+'</dd>').join('')+'</dl>';}
function completePage(id){const p=state.people.find(p=>p.id===Number(id));if(!p)return myPage();return frame(title('THANK YOU','また会える日を、楽しみに。')+`<div class="panel"><div class="success-mark">✓</div><h2>サンプル${editId?'変更':'申込'}を保存しました。</h2><p>申込番号 <strong>${esc(p.number)}</strong></p><p>${esc(p.name)} さん ／ 3年${p.class}組</p><div class="notice">これは実際の同窓会への申込ではありません。メール送信・振込はありません。操作内容はこの端末のブラウザー内だけに保存されています。</div><div class="button-row"><a class="btn" href="#/my">自分の申込を確認 →</a><a class="btn btn-outline" href="#/classes/${p.class}">クラスの名簿を見る</a></div></div>`,'narrow');}
function myPage(){const p=state.people.find(p=>p.id===selectedPerson)||state.people[0],paid=R.totalPaid(state,p.id),d=R.due(state,p);selectedPerson=p.id;return frame(title('MY REGISTRATION','自分の申込を確認する。','本番は本人認証が必要です。今回のサンプルでは架空の申込を切り替えて体験できます。')+notice+`<div class="panel">${select('demoPerson','確認する架空の申込',state.people.map(p=>[p.id,p.number+' / '+p.name]),p.id)}<div class="section-head"><div><h2>${esc(p.name)} さん</h2><p>${esc(p.number)} ／ 3年${p.class}組 ${pill(p.status)}</p></div>${pill(R.paymentLabel(state,p),d!==0)}</div><div class="stats-grid"><div class="stat"><small>仮請求額</small><strong>${yen(p.status==='cancelled'?0:p.amount)}</strong></div><div class="stat"><small>入金割当（架空）</small><strong>${yen(paid)}</strong></div><div class="stat"><small>${d<0?'過払い・返金検討':'未入金・不足'}</small><strong>${yen(Math.abs(d))}</strong></div><div class="stat"><small>名前の掲載</small><strong style="font-size:19px">${p.public?'掲載する':'掲載しない'}</strong></div></div>${details([['氏名',p.name],['メール',p.email],['住所',p.address],['電話',p.phone],['申込期限（仮）',state.settings.registration],['入金期限（仮）',state.settings.payment],['修正期限（仮）',state.settings.change],['キャンセル期限（仮）',state.settings.cancel]])}${R.active(p)?`<div class="button-row"><button class="btn" data-action="edit-person" data-id="${p.id}" ${state.settings.clock>state.settings.change?'disabled':''}>申込内容を変更</button><button class="btn btn-outline" data-action="cancel-person" data-id="${p.id}" ${state.settings.clock>state.settings.cancel?'disabled':''}>欠席に変更する</button></div>`:'<p class="muted">欠席の申請・取消状況は幹事が確認します。</p>'}<p class="mini-note">現在の判定日（仮）：${esc(state.settings.clock)}。入金期限を過ぎても自動で取消にはしません。</p></div><div class="panel"><h3>この申込の操作履歴</h3>${history(state.logs.filter(l=>l.entity===p.number))}</div>`);}
function history(logs){return logs.length?'<div class="history">'+logs.slice().reverse().map(l=>'<div class="history-item"><small>'+esc(date(l.at))+' ／ '+esc(l.actor)+'</small><p><strong>'+esc(l.action)+'</strong> '+pill(l.result,l.result!=='成功')+'</p><p>'+esc(l.reason)+'</p></div>').join('')+'</div>':'<p class="muted">この申込の追加操作はまだありません。</p>';}
function galleryPage(){const ended=state.settings.clock>state.settings.photoEnd,photos=state.photos.filter(p=>p.published);return frame(title('PHOTO ALBUM','あの日の笑顔を、持ち帰ろう。','サンプルでは見本アカウントでログインして表示します。本番は参加者限定に切り替える予定です。')+`<div class="notice notice-green">当日の写真はまだありません。現在の画像はオリジナルのイラスト見本です。追加画像はアップロードした方のブラウザー内だけで見られます。</div><div class="gallery-toolbar"><span>${ended?'仮の写真公開期限を過ぎています。':photos.length+'枚のイラスト・追加画像'}</span><a href="#/admin/photos" class="text-link">幹事の写真登録を試す ↗</a></div>${ended?'<div class="panel empty">公開期限（仮）を過ぎています。幹事設定で変更できます。</div>':'<div class="gallery-grid">'+albumCards(photos)+'</div>'}`);}
function photoPage(id){const p=state.photos.find(x=>x.id===Number(id)&&x.published);if(!p||state.settings.clock>state.settings.photoEnd)return frame(title('ALBUM','この画像は公開されていません。')+'<a class="btn" href="#/gallery">アルバムへ戻る</a>');return frame(title('PHOTO ALBUM',esc(p.title),esc(p.album))+'<div class="panel"><img class="large-photo" src="'+esc(p.src)+'" alt="'+esc(p.title)+'"><div class="button-row"><button class="btn" data-action="download-photo" data-id="'+p.id+'">見本画像をダウンロード ↓</button><a href="#/gallery" class="btn btn-outline">アルバムへ戻る</a></div><p class="mini-note">'+(p.sample?'実際の学校・会場・人物の写真ではありません。':'この画像はこのブラウザー内だけに保存されています。')+'</p></div>');}
function adminShell(section,body){const links=[['','参加者・集計'],['bank','CSV・入金照合'],['logs','入金操作ログ'],['photos','写真管理'],['settings','期限・大会設定'],['mail','開発メール']];return frame('<div class="admin-title-row">'+title('ORGANIZER DEMO','幹事の仕事も、分かりやすく。','ここは誰でも開ける架空データ専用の管理画面サンプルです。')+'<label class="actor-select">操作する幹事<select id="actorSelect"><option '+(actor.startsWith('幹事A')?'selected':'')+'>幹事A（サンプル）</option><option '+(actor.startsWith('幹事B')?'selected':'')+'>幹事B（サンプル）</option></select></label></div>'+notice+'<nav class="admin-tabs" aria-label="幹事メニュー">'+links.map(([s,t])=>'<a href="#/admin'+(s?'/'+s:'')+'" class="'+(section===s?'active':'')+'">'+t+'</a>').join('')+'</nav>'+body);}
function adminPage(){const c=R.counts(state),billed=state.people.reduce((v,p)=>v+(p.status==='cancelled'?0:p.amount),0),paid=state.allocations.filter(a=>a.active).reduce((v,a)=>v+a.amount,0),unpaid=state.people.reduce((v,p)=>v+Math.max(0,R.due(state,p)),0);return adminShell('',`<div class="stats-grid"><div class="stat"><small>参加予定人数</small><strong>${c.total}人</strong><em>申込累計 ${state.people.length}件 ／ 10クラス</em></div><div class="stat"><small>請求合計（仮）</small><strong>${yen(billed)}</strong><em>当初の会費を保持</em></div><div class="stat"><small>入金割当（架空）</small><strong>${yen(paid)}</strong><em>実際の入金ではありません</em></div><div class="stat"><small>未入金・不足</small><strong>${yen(unpaid)}</strong><em>過払いは別途確認</em></div></div><div class="panel"><div class="section-head"><h3>クラスごとの参加予定</h3><span class="muted">合計 ${c.total}人</span></div>${classCards()}</div><div class="panel"><div class="section-head"><h3>参加者を確認</h3><button class="btn btn-outline btn-small" data-action="export-people">参加者CSV ↓</button></div><div class="filter-row"><input class="search" id="peopleQuery" aria-label="参加者の検索" placeholder="名前・旧姓・申込番号・メール"><select class="filter" id="peopleClass" aria-label="クラスの絞り込み"><option value="">全クラス</option>${Array.from({length:10},(_,i)=>'<option value="'+(i+1)+'">3年'+(i+1)+'組</option>').join('')}</select><select class="filter" id="peopleStatus" aria-label="入金状態の絞り込み"><option value="">すべての状態</option><option>未入金</option><option>一部入金</option><option>入金済</option><option>過払い・返金検討</option><option>欠席・取消</option></select></div><div id="peopleTable"></div></div>`);}
function renderPeople(){const el=document.querySelector('#peopleTable');if(!el)return;const q=document.querySelector('#peopleQuery').value.toLowerCase(),cl=document.querySelector('#peopleClass').value,st=document.querySelector('#peopleStatus').value;const ps=state.people.filter(p=>(!cl||p.class===Number(cl))&&(!q||[p.name,p.oldname,p.number,p.email,p.payer].join(' ').toLowerCase().includes(q))&&(!st||(st==='欠席・取消'?!R.active(p):R.paymentLabel(state,p)===st)));el.innerHTML=table(['申込番号','氏名 / クラス','参加状況','連絡先（架空）','請求額','入金割当','差額','入金状況'],ps.map(p=>['<button class="link" data-action="person-detail" data-id="'+p.id+'">'+esc(p.number)+'</button>',esc(p.name)+'<br><small>3年'+p.class+'組</small>',pill(p.status),esc(p.email)+'<br><small>'+esc(p.phone)+'</small>',yen(p.status==='cancelled'?0:p.amount),yen(R.totalPaid(state,p.id)),yen(R.due(state,p)),pill(R.paymentLabel(state,p),R.due(state,p)!==0)]));}
function personDetail(id){const p=state.people.find(p=>p.id===id);const as=state.allocations.filter(a=>a.personId===id);openModal('<div class="eyebrow">REGISTRATION DETAIL</div><h2>'+esc(p.name)+' さん</h2><p>'+esc(p.number)+' ／ '+pill(p.status)+'</p>'+details([['クラス','3年'+p.class+'組'],['メール',p.email],['住所',p.address],['電話',p.phone],['申告名義',p.payer],['名前の公開',p.public?p.display:'非掲載'],['仮請求',yen(p.status==='cancelled'?0:p.amount)],['入金割当',yen(R.totalPaid(state,p.id))],['差額',yen(R.due(state,p))]])+'<h3>入金割当の履歴</h3>'+table(['割当ID','明細','金額','状態','操作'],as.map(a=>['#'+a.id,'#'+a.transactionId,yen(a.amount),a.active?'有効':'取消済',a.active?'<button class="link" data-action="unallocate" data-id="'+a.id+'">取消・訂正</button>':esc(a.cancelReason||'')]))+(p.status==='cancel_requested'?'<button class="btn btn-danger" data-action="approve-cancel" data-id="'+id+'">欠席・取消を承認する</button><button class="btn btn-outline" data-action="reject-cancel" data-id="'+id+'">参加予定に戻す</button>':'')+(R.due(state,p)<0?'<button class="btn btn-outline" data-action="refund" data-id="'+id+'">返金予定を記録（模擬）</button>':'')+'<h3>操作履歴</h3>'+history(state.logs.filter(l=>l.entity===p.number)));}
function bankPage(){return adminShell('bank',`<div class="panel"><h3>銀行CSVを取り込む</h3><p class="muted">架空のUFJ形式CSVで取込・候補確認・入金割当を試せます。振込名義の列は未確定として扱います。</p><div class="button-row"><button class="btn btn-outline btn-small" data-action="fixture-download" data-id="1">前半CSVを取得 ↓</button><button class="btn btn-outline btn-small" data-action="fixture-download" data-id="2">期間重複CSVを取得 ↓</button><button class="btn btn-outline btn-small" data-action="fixture-download" data-id="3">要確認CSVを取得 ↓</button></div><label class="file-drop">架空CSVを選択 <input type="file" id="bankFile" accept=".csv"></label><div class="button-row"><button class="btn" data-action="import-fixture" data-id="1">前半の架空CSVで試す</button><button class="btn btn-outline" data-action="import-fixture" data-id="2">重複期間のCSVで試す</button><button class="btn btn-outline" data-action="import-fixture" data-id="3">要確認CSVで試す</button></div><p class="mini-note">ボタンならファイル選択不要。何度でも同一ファイル再取込・重複期間を確認できます。実銀行明細は使用しないでください。</p></div><div class="panel"><h3>取込結果</h3>${state.imports.length?state.imports.slice().reverse().map(i=>`<details><summary>取込 #${i.id} ${esc(i.filename)} · ${i.count}明細 / 重複候補${i.duplicates} / エラー${i.errors.length}</summary><p class="mini-note">${esc(date(i.at))} ／ ${esc(i.actor)} ／ 管理情報${i.managementRows}行と見出しを区別</p>${table(['行','明細ID','内容'],i.rows.map(r=>[r.line,'#'+r.transactionId,esc(r.raw.join(' / '))]).concat(i.errors.map(r=>[r.line,'エラー',esc(r.error)+' / '+esc(r.raw.join(' / '))])))}<details><summary>元のCSVを見る（このブラウザー内）</summary><pre>${esc(i.source)}</pre></details></details>`).join(''):'<p class="muted">まだCSVを取り込んでいません。</p>'}</div><div class="panel"><div class="section-head"><h3>明細の照合</h3><button class="btn btn-outline btn-small" data-action="export-payments">入金一覧CSV ↓</button></div><div class="filter-row"><select class="filter" id="bankState" aria-label="銀行明細の状態"><option value="imported">今回の取込明細</option><option value="pending">確認待ち</option><option value="confirmed">確認済</option><option value="all">すべて（初期入金含む）</option></select></div><div id="bankTable"></div></div>`);}
function renderBank(){const el=document.querySelector('#bankTable');if(!el)return;const st=document.querySelector('#bankState').value;const ts=state.transactions.filter(t=>st==='all'||st==='imported'&&t.importId||t.state===st).slice().reverse();el.innerHTML=table(['明細','日付','内容','入金 / 出金','残高','未割当','状態','操作'],ts.map(t=>['#'+t.id,esc(t.date),esc(t.memo)+'<br><small>'+esc(t.review)+'</small>',yen(t.credit)+' / '+yen(t.debit),yen(t.balance),yen(t.credit-R.used(state,t.id)),pill(t.state,t.state==='pending'),'<button class="link" data-action="transaction-detail" data-id="'+t.id+'">確認・割当</button>']));}
function transactionDetail(id){const t=state.transactions.find(t=>t.id===id);let b='<div class="eyebrow">BANK RECONCILIATION</div><h2>明細 #'+id+'</h2>'+details([['日付',t.date],['摘要（参考）',t.memo],['入金額',yen(t.credit)],['出金額',yen(t.debit)],['残高',yen(t.balance)],['未割当',yen(t.credit-R.used(state,id))],['状態',label[t.state]]])+'<div class="notice">'+esc(t.review)+'</div><details><summary>元データ9列</summary><pre>'+esc(JSON.stringify(t.raw,null,2))+'</pre></details>';
 if(t.state==='pending')b+='<form id="decisionForm" data-id="'+id+'">'+select('decision','明細の判定',[['confirmed','入金を確認（重複候補は別取引として保持）'],['excluded','重複・対象外として除外']],'confirmed')+field('reason','名義・資金化・重複を確認した理由')+'<p class="error-text" id="modalError" role="alert"></p><button class="btn">判定を記録</button></form>';
 if(t.state==='confirmed'&&t.credit-R.used(state,id)>0){let candidates=state.people.filter(p=>p.status!=='cancelled').map(p=>{const reasons=[];if(t.memo.includes(p.number))reasons.push('申込番号一致');if(p.payer&&t.memo.includes(p.payer))reasons.push('申告名義を含む（参考）');if(R.due(state,p)===t.credit-R.used(state,id))reasons.push('金額一致');return {p,reasons};}).filter(c=>c.reasons.length).sort((a,b)=>b.reasons.length-a.reasons.length).slice(0,5);b+='<h3>照合候補（自動確定しません）</h3>'+table(['番号','氏名','理由'],candidates.map(({p,reasons})=>[esc(p.number),esc(p.name),esc(reasons.join(' / '))]))+'<form id="allocateForm" data-id="'+id+'">'+field('number','割当先の申込番号',candidates[0]?.p.number||'')+field('amount','割当金額',t.credit-R.used(state,id),'number')+field('reason','確認根拠・割当理由')+'<p class="error-text" id="modalError" role="alert"></p><button class="btn">入金を確定・割当</button></form>';}
 openModal(b);
}
function logsPage(){return adminShell('logs','<div class="panel"><div class="section-head"><div><h3>入金と管理の操作ログ</h3><p class="muted">誰が・いつ・どの明細を・どう処理したか。変更前後と訂正理由を追えます。</p></div><button class="btn btn-outline btn-small" data-action="export-logs">表示中のログCSV ↓</button></div><div class="filter-row"><input class="search" id="logQuery" aria-label="ログ検索" placeholder="申込番号・操作・明細ID・理由"><select class="filter" id="logActor" aria-label="ログ担当者"><option value="">すべての担当者</option><option>幹事A（サンプル）</option><option>幹事B（サンプル）</option><option>申込者（サンプル）</option></select><input type="date" id="logFrom" aria-label="ログ開始日"><input type="date" id="logTo" aria-label="ログ終了日"></div><p class="mini-note">業務画面にログ編集・個別削除機能はありません。このサンプルの記録は端末内のみで、本番の改ざん防止・共通保管機能ではありません。</p><div id="logTable"></div></div>');}
function filteredLogs(){const q=(document.querySelector('#logQuery')?.value||'').toLowerCase(),a=document.querySelector('#logActor')?.value||'',from=document.querySelector('#logFrom')?.value||'',to=document.querySelector('#logTo')?.value||'';return state.logs.filter(l=>(!q||JSON.stringify(l).toLowerCase().includes(q))&&(!a||l.actor===a)&&(!from||l.at.slice(0,10)>=from)&&(!to||l.at.slice(0,10)<=to)).slice().reverse();}
function renderLogs(){const el=document.querySelector('#logTable');if(!el)return;el.innerHTML=table(['ログID・日時','担当者','操作','対象','結果','理由・変更前後'],filteredLogs().map(l=>['#'+l.id+'<br>'+esc(date(l.at)),esc(l.actor),esc(l.action),esc(l.entity),pill(l.result,l.result!=='成功'),esc(l.reason)+'<details><summary>変更前後</summary><pre>'+esc(JSON.stringify({before:l.before,after:l.after},null,2))+'</pre></details>']));}
function settingsPage(){const s=state.settings;return adminShell('settings','<div class="panel"><h3>大会案内と、個別の期限設定</h3><div class="notice">開催日・会費は未定です。以下の期限・会費・判定日はすべて操作確認用の仮値です。</div><form id="settingsForm"><div class="grid-2">'+field('dateLabel','案内に表示する開催日',s.dateLabel)+field('venue','会場',s.venue)+field('fee','サンプル会費（円）',s.fee,'number')+field('capacity','参加定員（会場上限）',s.capacity,'number')+field('classSize','参加状況グラフの基準人数（1クラス・仮）',s.classSize||47,'number')+field('open','申込受付開始日（仮）',s.open,'date')+field('registration','参加申込期限（仮）',s.registration,'date')+field('payment','入金期限（仮）',s.payment,'date')+field('change','内容修正期限（仮）',s.change,'date')+field('cancel','キャンセル期限（仮）',s.cancel,'date')+field('photoEnd','写真公開終了日（仮）',s.photoEnd,'date')+field('clock','期限判定用の日付（デモ専用）',s.clock,'date')+'</div><p class="mini-note">各期限は独立しています。期限当日の日本時間23:59:59まで、という本番仕様に対し、サンプルではこの判定日と日付で比較します。会費変更は新規申込だけに適用し、既存申込の請求額を上書きしません。</p>'+field('reason','設定変更の理由')+'<p id="formError" class="error-text" role="alert"></p><button class="btn">設定と変更ログを保存</button></form></div><div class="panel"><h3>サンプルのバックアップ・初期化</h3><p class="muted">端末内の操作内容をJSONで保存できます。実際の個人情報は保存しないでください。</p><div class="button-row"><button class="btn btn-outline" data-action="backup">この端末のデモをバックアップ ↓</button><label class="btn btn-outline">バックアップを復元<input id="restoreFile" type="file" accept=".json" hidden></label><button class="btn btn-danger" data-action="reset">架空データへ初期化</button></div></div>');}
function photosAdmin(){return adminShell('photos','<div class="panel"><h3>写真を登録する操作を試す</h3><p class="muted">見本や公開可能なテスト画像だけを使ってください。画像は送信されず、このブラウザー内に保存します。</p><label class="file-drop">JPEG・PNGのテスト画像を追加<input id="photoFiles" type="file" accept="image/jpeg,image/png" multiple></label><p class="mini-note">1回4枚、1枚5MB・2000万画素まで。向きを補正して最大1600pxのJPEGにし、EXIFを除いて保存します。実際の同窓会写真の公開機能は本番で別途実装します。</p></div><div class="panel"><h3>アルバムの公開・非公開</h3>'+table(['見本','タイトル','アルバム','状態','操作'],state.photos.map(p=>['<img class="upload-preview" src="'+esc(p.src)+'" alt="'+esc(p.title)+'">',esc(p.title),esc(p.album),p.published?'公開':'非公開','<button class="link" data-action="toggle-photo" data-id="'+p.id+'">'+(p.published?'非公開にする':'公開する')+'</button>']))+'</div>');}
function mailPage(){return adminShell('mail','<div class="panel"><h3>開発メール（すべて未送信）</h3><p class="muted">申込・変更・入金確認に伴って記録するサンプルです。メールサーバーへの接続はありません。</p>'+(state.mail.length?state.mail.slice().reverse().map(m=>'<details><summary>'+esc(m.subject)+' / '+esc(state.people.find(p=>p.id===m.personId)?.number||'')+'</summary><p class="mini-note">'+esc(date(m.at))+'</p><pre>'+esc(m.body)+'</pre></details>').join(''):'<p class="empty">申込や入金を操作すると、ここに通知の見本が記録されます。</p>')+'</div>');}
function route(){const path=(location.hash.slice(1)||'/').split('/').filter(Boolean),part=path[0]||'';window.ReunionMenu.set(false);if(part!=='register'&&part!=='confirm'&&part!=='complete')editId=null;let body;
 switch(part){case '':body=home();break;case 'classes':body=classes(path[1]);break;case 'register':editId=path[1]&&state.people.some(p=>p.id===Number(path[1]))?Number(path[1]):null;body=registerPage();break;case 'confirm':body=confirmPage();break;case 'complete':body=completePage(path[1]);break;case 'my':body=myPage();break;case 'gallery':body=galleryPage();break;case 'photo':body=photoPage(path[1]);break;case 'admin':switch(path[1]||''){case '':body=adminPage();break;case 'bank':body=bankPage();break;case 'logs':body=logsPage();break;case 'settings':body=settingsPage();break;case 'photos':body=photosAdmin();break;case 'mail':body=mailPage();break;default:body=adminPage();}break;default:body=frame(title('NOT FOUND','ページが見つかりません。')+'<a class="btn" href="#/">トップへ</a>');}
 main.innerHTML=body;document.querySelectorAll('#mainNav>a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#/'+part));renderPeople();renderBank();renderLogs();window.scrollTo(0,0);document.title=(part==='admin'?'幹事画面｜':part==='classes'?'参加予定名簿｜':part==='gallery'?'アルバム｜':'')+'岡崎北高等学校1987年卒同窓会【サンプル】';if(!storageOK)toast('保存機能が制限されています。この画面内でのみお試しいただけます。');}
function openModal(html){document.querySelector('#modalBody').innerHTML=html;document.querySelector('#modal').showModal();}
function closeModal(){document.querySelector('#modal').close();}
function reasonDialog(action,id,heading,extra=''){openModal('<h2>'+heading+'</h2><p>元の記録を残し、担当者と理由を操作ログへ保存します。</p><form id="reasonForm" data-action="'+action+'" data-id="'+id+'">'+extra+field('reason','処理・判断の理由')+'<p id="modalError" class="error-text" role="alert"></p><button class="btn">記録する</button></form>');}
function help(){openModal('<div class="eyebrow">HOW TO TRY</div><h2>「こんな同窓会サイト」を、みんなで。</h2><p>これはLINEグループでデザイン・操作を見てもらう公開サンプルです。本番の申込受付ではありません。見本アカウントでログインし、本人・幹事・代表幹事の画面を体験できます。</p><ol><li>「参加申込を試す」→架空情報を自動入力→確認・確定。</li><li>「みんなの参加予定」でクラス別・全体人数を確認。</li><li>「幹事画面」→「CSV・入金照合」で架空CSVを取込・確認・割当。</li><li>「入金操作ログ」で担当者・変更前後・理由を確認。</li><li>「期限・大会設定」で申込・入金・修正・キャンセル期限を個別変更。</li><li>「フォトアルバム」で見本画像を表示・ダウンロード。</li></ol><p>保存は各端末のブラウザー内です。ほかの人の操作には影響せず、端末を変えると同じデータにはなりません。実際の氏名・住所・メール・銀行明細・写真は入力しないでください。本番では本人認証・幹事認証・共通DB・ログ保護・写真のアクセス制限を別途実装します。</p><button class="btn" id="helpClose">サンプルを見てみる →</button>');}
async function importText(text,name){let result;try{result=change(s=>R.importCSV(s,text,name,actor));toast(result.repeated?'同じ内容のCSV：再取込を抑止しました。':result.count+'明細を取込・重複候補'+result.duplicates+'件・エラー'+result.errors.length+'件');route();}catch(e){failed('CSV取込失敗','import',e);}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=Number(b.dataset.id);try{switch(action){
 case 'edit-person':editId=id;draft=null;location.hash='/register/'+id;break;
 case 'cancel-person':reasonDialog(action,id,'欠席への変更を申請する');break;
 case 'person-detail':personDetail(id);break;
 case 'transaction-detail':transactionDetail(id);break;
 case 'unallocate':reasonDialog(action,id,'入金割当を取り消す');break;
 case 'approve-cancel':reasonDialog(action,id,'欠席・取消を承認する');break;
 case 'reject-cancel':reasonDialog(action,id,'参加予定に戻す');break;
 case 'refund':reasonDialog(action,id,'返金予定を記録する（送金なし）',field('amount','返金予定額',Math.max(0,-R.due(state,state.people.find(p=>p.id===id))),'number'));break;
 case 'fixture-download':download('同窓会_架空CSV_'+id+'.csv',R.fixtures(id));break;
 case 'import-fixture':await importText(R.fixtures(id),'架空CSV_'+id+'.csv');break;
 case 'export-people':change(s=>R.audit(s,actor,'参加者一覧CSV出力','export',null,{count:s.people.length},'架空データの出力'));download('同窓会_架空参加者.csv',R.toCSV([['申込番号','氏名','クラス','メール','住所','電話','参加状況','入金状況'],...state.people.map(p=>[p.number,p.name,'3年'+p.class+'組',p.email,p.address,p.phone,label[p.status],R.paymentLabel(state,p)])]));toast('架空参加者CSVを保存しました');break;
 case 'export-payments':change(s=>R.audit(s,actor,'入金一覧CSV出力','export',null,{count:s.people.length},'架空入金の出力'));download('同窓会_架空入金一覧.csv',R.toCSV([['番号','氏名','仮請求','入金割当','差額','状態'],...state.people.map(p=>[p.number,p.name,p.status==='cancelled'?0:p.amount,R.totalPaid(state,p.id),R.due(state,p),R.paymentLabel(state,p)])]));toast('入金一覧を保存しました');break;
 case 'export-logs':{const logs=filteredLogs();change(s=>R.audit(s,actor,'操作ログCSV出力','export',null,{count:logs.length},'検索条件に一致するログを出力'));download('同窓会_操作ログ.csv',R.toCSV([['ID','日時','担当者','操作','対象','結果','理由','変更前','変更後'],...logs.map(l=>[l.id,l.at,l.actor,l.action,l.entity,l.result,l.reason,JSON.stringify(l.before),JSON.stringify(l.after)])]));renderLogs();toast('表示中の操作ログを保存しました');break;}
 case 'toggle-photo':change(s=>{const p=s.photos.find(p=>p.id===id),before=p.published;p.published=!p.published;R.audit(s,actor,'写真公開状態の変更','photo:'+id,{published:before},{published:p.published},'見本画像の公開操作');});route();toast('公開状態と操作ログを保存しました');break;
 case 'download-photo':{const p=state.photos.find(p=>p.id===id&&p.published);if(!p||state.settings.clock>state.settings.photoEnd)throw new Error('公開中の画像ではありません。');const a=document.createElement('a');a.href=p.src;a.download='同窓会_見本_'+id+(p.sample?'.svg':'.jpg');a.click();toast('見本画像のダウンロードを開始しました');break;}
 case 'backup':download('同窓会_サンプルバックアップ.json',JSON.stringify(state,null,2),'application/json');break;
 case 'reset':openModal('<h2>この端末のデモを初期状態に戻しますか？</h2><p>バックアップJSONをダウンロードしてから、架空の初期データに戻します。他の方のデモには影響しません。</p><button class="btn btn-danger" id="resetConfirm">バックアップして初期化する</button>');break;
 }}catch(e){failed(action,b.dataset.id||'demo',e);}});
document.addEventListener('click',ev=>{if(ev.target.closest('#fillDemo')){const f=document.querySelector('#registrationForm');const vals={class:'2',name:'見本 再会',kana:'ミホン サイカイ',oldname:'',email:'reunion-demo@example.test',emailConfirm:'reunion-demo@example.test',postal:'000-0000',address:'愛知県架空市見本町1-2-3',phone:'000-0000-0000',payer:'ミホン サイカイ',display:'見本 再会',public:'yes',note:'サンプル申込です。実際の個人情報は入力していません。'};for(const[k,v]of Object.entries(vals))f.elements[k].value=v;f.elements.sampleOnly.checked=true;toast('架空のサンプル情報を入力しました');}
 if(ev.target.closest('#confirmRegistration')){const confirmButton=ev.target.closest('#confirmRegistration');if(confirmButton.disabled)return;confirmButton.disabled=true;try{const p=editId?change(s=>R.editPerson(s,editId,draft)):change(s=>R.register(s,draft));selectedPerson=p.id;sessionStorage.setItem('kita-demo-person',String(p.id));draft=null;location.hash='/complete/'+p.id;}catch(e){confirmButton.disabled=false;toast(e.message);}}
 if(ev.target.closest('#resetConfirm')){download('同窓会_初期化前バックアップ.json',JSON.stringify(state,null,2),'application/json');try{localStorage.setItem(KEY,JSON.stringify(R.seed()));state=R.seed();selectedPerson=1;sessionStorage.removeItem('kita-demo-person');closeModal();route();toast('架空データへ初期化しました');}catch(e){toast(e.message);}}
 if(ev.target.closest('#helpClose'))closeModal();});
document.addEventListener('submit',ev=>{const f=ev.target;if(!['registrationForm','decisionForm','allocateForm','reasonForm','settingsForm'].includes(f.id))return;ev.preventDefault();const d=Object.fromEntries(new FormData(f));try{
 if(f.id==='registrationForm'){draft=draftFrom(f);R.validatePerson(state,draft,!!editId);location.hash='/confirm';return;}
 if(f.id==='decisionForm'){change(s=>R.decide(s,Number(f.dataset.id),d.decision,d.reason,actor));const id=Number(f.dataset.id);closeModal();route();transactionDetail(id);toast('明細の判定とログを保存しました');return;}
 if(f.id==='allocateForm'){const p=state.people.find(p=>p.number===d.number.trim());if(!p)throw new Error('その申込番号はありません。');change(s=>R.allocate(s,Number(f.dataset.id),p.id,Number(d.amount),d.reason,actor));closeModal();route();toast('入金割当と操作ログを保存しました');return;}
 if(f.id==='settingsForm'){if(!d.reason.trim())throw new Error('変更理由を入力してください。');if(!Number.isInteger(Number(d.classSize))||Number(d.classSize)<1||Number(d.classSize)>1000)throw new Error('グラフの基準人数は1〜1000人です。');if(d.open>d.registration)throw new Error('申込受付開始日が申込期限より後になっています。');if(!Number.isSafeInteger(Number(d.fee))||Number(d.fee)<0||!Number.isSafeInteger(Number(d.capacity))||Number(d.capacity)<1)throw new Error('会費・定員は有効な整数を入力してください。');change(s=>{const before=R.clone(s.settings);const settings={...s.settings};for(const k of Object.keys(settings)){if(k==='fee'||k==='capacity'||k==='classSize')settings[k]=Number(d[k]);else settings[k]=d[k];}s.settings=settings;R.audit(s,actor,'大会・期限設定変更','settings',before,settings,d.reason);});route();toast('それぞれの期限と変更ログを保存しました');return;}
 if(f.id==='reasonForm'){const id=Number(f.dataset.id),action=f.dataset.action;if(!d.reason.trim())throw new Error('理由を入力してください。');change(s=>{if(action==='cancel-person')return R.cancel(s,id,d.reason);if(action==='unallocate')return R.unallocate(s,id,d.reason,actor);const p=s.people.find(p=>p.id===id);if(action==='approve-cancel'){if(p.status!=='cancel_requested')throw new Error('欠席変更申請中ではありません。');const before={status:p.status,amount:p.amount};p.status='cancelled';p.revision++;R.audit(s,actor,'欠席・取消の承認',p.number,before,{status:p.status,billed:0,revision:p.revision,refundConsideration:Math.max(0,-R.due(s,p))},d.reason);}if(action==='reject-cancel'){if(p.status!=='cancel_requested')throw new Error('欠席変更申請中ではありません。');p.status='active';R.audit(s,actor,'欠席申請を参加予定へ戻す',p.number,{status:'cancel_requested'},{status:p.status},d.reason);}if(action==='refund'){const amount=Number(d.amount),planned=s.refunds.filter(r=>r.personId===id&&r.status==='予定').reduce((v,r)=>v+r.amount,0);if(!Number.isSafeInteger(amount)||amount<=0||amount>Math.max(0,-R.due(s,p))-planned)throw new Error('未処理の過払い額以内の返金予定額を入力してください。');const r={id:s.refunds.length+1,personId:id,amount,status:'予定',reason:d.reason,at:new Date().toISOString()};s.refunds.push(r);R.audit(s,actor,'返金予定の記録（送金なし）',p.number,null,r,d.reason);}});closeModal();route();toast('処理と操作ログを保存しました');}
 }catch(e){const el=f.querySelector('#formError,#modalError');if(el)el.textContent=e.message;if(f.id!=='registrationForm')failed(f.id,f.dataset.id||'settings',e);}});
document.addEventListener('input',ev=>{if(['peopleQuery','peopleClass','peopleStatus'].includes(ev.target.id))renderPeople();if(['logQuery','logActor','logFrom','logTo'].includes(ev.target.id))renderLogs();});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='demoPerson'){selectedPerson=Number(el.value);sessionStorage.setItem('kita-demo-person',String(selectedPerson));route();}if(el.id==='actorSelect'){actor=el.value;toast('操作担当を '+actor+' に切り替えました');}if(el.id==='bankState')renderBank();if(['peopleClass','peopleStatus'].includes(el.id))renderPeople();if(['logActor','logFrom','logTo'].includes(el.id))renderLogs();
 if(el.id==='bankFile'&&el.files[0]){try{const file=el.files[0];if(file.size>1500000)throw new Error('CSVは1.5MB以下でお試しください。');const bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(!text.includes(R.HEADERS.join(','))&&!text.includes('"日付"'))text=new TextDecoder('shift_jis').decode(bytes);await importText(text,file.name);}catch(e){toast(e.message);}}
 if(el.id==='photoFiles'&&el.files.length){try{if(el.files.length>4)throw new Error('1回に4枚まで選択してください。');const images=[];for(const f of el.files){if(!['image/jpeg','image/png'].includes(f.type)||f.size>5e6)throw new Error('JPEG・PNG、1枚5MB以内で選択してください。');const uri=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('画像として読み込めません。'));img.src=uri;});if(img.width*img.height>20000000)throw new Error('画像は2000万画素以内にしてください。');const scale=Math.min(1,1600/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);images.push({title:f.name.replace(/\.[^.]*$/,''),src:canvas.toDataURL('image/jpeg',.78)});}change(s=>{for(const image of images){const id=Math.max(0,...s.photos.map(p=>p.id))+1;s.photos.push({...image,id,album:'この端末のテスト画像',published:false,sample:false});R.audit(s,actor,'テスト画像を端末内に登録','photo:'+id,null,{title:image.title,published:false},'外部送信なし・公開前確認');}});route();toast(images.length+'枚を非公開で追加しました。公開ボタンでアルバムへ出せます。');}catch(e){toast(e.message);}}
 if(el.id==='restoreFile'&&el.files[0]){try{if(el.files[0].size>4000000)throw new Error('バックアップは4MB以内にしてください。');const obj=JSON.parse(await el.files[0].text());if(obj.schema!==1||!Array.isArray(obj.people)||!Array.isArray(obj.logs)||!Array.isArray(obj.photos)||!obj.settings||!Array.isArray(obj.allocations)||!Array.isArray(obj.transactions)||!Array.isArray(obj.imports)||!Array.isArray(obj.mail)||!Array.isArray(obj.refunds))throw new Error('このデモのバックアップ形式ではありません。');for(const p of obj.photos)if(!/^assets\/[a-z-]+\.svg$/.test(p.src)&&!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.src)&&!R.seed().photos.some(v=>v.src===p.src))throw new Error('画像データの形式が不正です。');download('同窓会_復元前バックアップ.json',JSON.stringify(state,null,2),'application/json');R.audit(obj,actor,'サンプルバックアップ復元','demo',null,{people:obj.people.length},'端末内データの復元');localStorage.setItem(KEY,JSON.stringify(obj));state=obj;route();toast('この端末のデモを復元しました');}catch(e){toast('復元できません：'+e.message);}}
});
document.querySelector('#demoHelp').onclick=help;document.querySelector('#footerHelp').onclick=help;document.querySelector('#closeModal').onclick=closeModal;
window.addEventListener('hashchange',route);window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue){try{state=JSON.parse(ev.newValue);route();toast('同じブラウザーの別タブの変更を反映しました');}catch{}}});route();
